matcher:
{"source": "rule nsis_randomized_version_loader {
  strings:
    $nsis = "NullsoftInst" ascii
    $call = "CallWindowProcW" ascii
    $comment = "julaceous" wide
    $legal = "thegnhood skambudte tabslisterne" wide
  condition:
    uint16(0) == 0x5a4d and all of them
}
", "type": "yara"}

{"source": "rule msi_sfx_sideload_targets {
  strings:
    $version = "version.dll" ascii wide
    $cryptbase = "cryptbase.dll" ascii wide
  condition:
    uint32(0) == 0xe011cfd0 and $version and $cryptbase
}
", "type": "yara"}
